import type { MetadataRoute } from "next";

// Web app manifest (served at /manifest.webmanifest; Next injects <link rel="manifest">).
// Icons are the raster set generated by scripts/gen-icons.mjs from icon.svg [ORQ-47].
// Colors: dark #0a0a0a matches the black icon mark and the app's dark theme
// (globals.css dark --background oklch(0.141 0.005 285.823) ≈ near-black).
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Orqafy",
    short_name: "Orqafy",
    description:
      "Move as one — the all-in-one project & business operations platform for growing businesses.",
    start_url: "/",
    display: "standalone",
    background_color: "#0a0a0a",
    theme_color: "#0a0a0a",
    icons: [
      {
        src: "/icons/icon-192.png",
        sizes: "192x192",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icons/icon-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "any",
      },
    ],
  };
}
